const crypto = require('crypto');
// require de modulo nativo no Code node exige NODE_FUNCTION_ALLOW_BUILTIN=crypto na
// instancia. Falhar aqui, na borda, e melhor que aceitar webhook sem conferir assinatura:
// pagamento forjado provisiona barbearia de graca.

const entrada = $input.first();

// Header em minusculas: HTTP/2 entrega minuscula, HTTP/1.1 entrega como o remetente
// escreveu, e 'X-Signature' !== 'x-signature' num objeto JS.
const cab = {};
for (const [chave, valor] of Object.entries(entrada.json.headers || {})) {
  cab[chave.toLowerCase()] = Array.isArray(valor) ? valor[0] : valor;
}

const gateway = String((entrada.json.params || {}).gateway || '').toLowerCase();

// Os bytes exatos que chegaram, nao o objeto reserializado: JSON.stringify(JSON.parse(x))
// difere de x em ordem de chave, espaco e escape unicode, e um byte de diferenca derruba o
// HMAC. Vem do option rawBody do Webhook, que guarda o corpo cru em binary.data.
const bruto = ((entrada.binary || {}).data || {}).data;
const cru = bruto === undefined ? null : Buffer.from(bruto, 'base64').toString('utf8');
const corpo = cru === null ? (entrada.json.body || {}) : JSON.parse(cru);

function segredoDoAmbiente(nome) {
  const valor = $env[nome];
  if (!valor) throw new Error('variavel de ambiente ausente: ' + nome);
  return valor;
}

function iguais(a, b) {
  // Tempo constante: com === a comparacao para no primeiro byte diferente e o tempo da
  // resposta revela o prefixo correto, o que permite descobrir a assinatura byte a byte.
  // O sha256 dos dois lados iguala o tamanho, que timingSafeEqual exige.
  const da = crypto.createHash('sha256').update(String(a), 'utf8').digest();
  const db = crypto.createHash('sha256').update(String(b), 'utf8').digest();
  return crypto.timingSafeEqual(da, db);
}

function hmacHex(segredo, texto) {
  return crypto.createHmac('sha256', segredo).update(texto, 'utf8').digest('hex');
}

// 'ts=1700000000,v1=abc' -> { ts: ['...'], v1: ['...'] }. Lista por chave porque a Stripe
// manda mais de um v1 durante rotacao de segredo.
function camposDoHeader(valor) {
  const campos = {};
  for (const parte of String(valor || '').split(',')) {
    const corte = parte.indexOf('=');
    if (corte <= 0) continue;
    const chave = parte.slice(0, corte).trim();
    if (campos[chave] === undefined) campos[chave] = [];
    campos[chave].push(parte.slice(corte + 1).trim());
  }
  return campos;
}

let evento_externo_id;
let recurso_id;
let tipo_externo;

if (gateway === 'mercadopago') {
  const campos = camposDoHeader(cab['x-signature']);
  const ts = (campos.ts || [])[0];
  const v1 = (campos.v1 || [])[0];
  if (!ts || !v1) throw new Error('mercadopago: x-signature ausente ou fora do formato ts=...,v1=...');

  recurso_id = String((corpo.data || {}).id || '');
  if (!recurso_id) throw new Error('mercadopago: corpo sem data.id');

  // Manifest posicional e literal, com ';' tambem no FIM e id alfanumerico em minusculas.
  // Tirar o ultimo ';', trocar a ordem dos campos ou omitir request-id que veio gera outro
  // HMAC e reprova assinatura valida.
  const manifest = 'id:' + recurso_id.toLowerCase() + ';request-id:' + (cab['x-request-id'] || '') + ';ts:' + ts + ';';
  if (!iguais(hmacHex(segredoDoAmbiente('MERCADOPAGO_WEBHOOK_SECRET'), manifest), v1)) {
    throw new Error('mercadopago: assinatura invalida');
  }

  // data.id e NAO corpo.id: corpo.id e o id da notificacao e muda a cada reentrega, o que
  // faria o dedupe de webhooks_recebidos aceitar o mesmo pagamento mais de uma vez.
  evento_externo_id = 'payment:' + recurso_id;
  tipo_externo = String(corpo.action || corpo.type || 'payment');
} else if (gateway === 'stripe') {
  if (cru === null) throw new Error('stripe: corpo cru indisponivel, ligue o option rawBody no Webhook');
  const campos = camposDoHeader(cab['stripe-signature']);
  const t = (campos.t || [])[0];
  const assinaturas = campos.v1 || [];
  if (!t || assinaturas.length === 0) throw new Error('stripe: Stripe-Signature ausente ou fora do formato t=...,v1=...');

  // Tolerancia de 300s. Sem ela a requisicao capturada vale para sempre: o que expira e o
  // timestamp, o HMAC continua correto.
  const idade = Math.abs(Math.floor(Date.now() / 1000) - Number(t));
  if (!Number.isFinite(idade) || idade > 300) throw new Error('stripe: timestamp fora da tolerancia de 300s');

  const esperado = hmacHex(segredoDoAmbiente('STRIPE_WEBHOOK_SECRET'), t + '.' + cru);
  // Mais de um v1 e rotacao de segredo em curso: basta um casar.
  if (!assinaturas.some(function (a) { return iguais(esperado, a); })) throw new Error('stripe: assinatura invalida');

  recurso_id = String(corpo.id || '');
  if (!recurso_id) throw new Error('stripe: corpo sem id do evento');
  evento_externo_id = recurso_id;
  tipo_externo = String(corpo.type || '');
} else if (gateway === 'asaas') {
  // O Asaas nao assina o corpo: manda no header o token configurado no painel dele. A
  // comparacao em tempo constante continua valendo, porque token descoberto byte a byte
  // tambem provisiona barbearia de graca.
  if (!iguais(cab['asaas-access-token'] || '', segredoDoAmbiente('ASAAS_WEBHOOK_TOKEN'))) {
    throw new Error('asaas: token de webhook invalido');
  }

  recurso_id = String((corpo.payment || {}).id || '');
  if (!recurso_id) throw new Error('asaas: corpo sem payment.id');
  tipo_externo = String(corpo.event || '');
  // corpo.id existe nas versoes novas do webhook. Sem ele, evento+pagamento mantem a chave
  // unica por tipo de evento: so com o pagamento, PAYMENT_RECEIVED seria descartado como
  // reentrega de PAYMENT_CONFIRMED do mesmo pagamento.
  evento_externo_id = corpo.id ? String(corpo.id) : tipo_externo + ':' + recurso_id;
} else {
  // O Switch seguinte roteia por este campo e nao tem saida de fallback: quem barra path
  // desconhecido e esta linha.
  throw new Error('gateway nao suportado no path: ' + gateway);
}

// Fecha o CHECK de 64 hex de webhooks_recebidos e serve para ver o gateway mandando
// conteudo diferente sob o mesmo id, sem guardar payload de pagamento no banco.
const corpo_hash = crypto.createHash('sha256').update(cru === null ? JSON.stringify(corpo) : cru, 'utf8').digest('hex');

// Sem segredo, sem token e sem corpo de pagamento no item: tudo o que sai daqui fica
// gravado no log de execucao do n8n.
return [{ json: {
  gateway: gateway,
  evento_externo_id: evento_externo_id,
  recurso_id: recurso_id,
  tipo_externo: tipo_externo,
  corpo_hash: corpo_hash
} }];

const crypto = require('crypto');

const borda = $('Valida assinatura').first().json;
const gateway = borda.gateway;

// O `id` do envelope e a chave de idempotencia da secao 3, entao ele NAO pode ser
// aleatorio: com randomUUID, a retentativa do no de provisionamento criaria um segundo
// tenant para o mesmo pagamento. Derivado de (gateway, evento_externo_id), duas execucoes
// do mesmo webhook produzem o mesmo id.
function uuidDeterministico(semente) {
  const b = Buffer.from(crypto.createHash('sha256').update(semente, 'utf8').digest().subarray(0, 16));
  b[6] = (b[6] & 15) | 64;
  b[8] = (b[8] & 63) | 128;
  const h = b.toString('hex');
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-' + h.slice(12, 16) + '-' + h.slice(16, 20) + '-' + h.slice(20);
}

// E.164 sem '+' (secao 2). Numero que nao da para classificar sai null: nono digito nao se
// adivinha e 10 digitos nao e necessariamente fixo. Telefone remendado manda a senha de
// primeiro acesso para outra pessoa.
function telefoneE164(valor) {
  const d = String(valor === null || valor === undefined ? '' : valor).replace(/\D/g, '');
  if (d.length >= 12 && d.length <= 15) return d;
  if (d.length === 10 || d.length === 11) return '55' + d;
  return null;
}

// Reais em double para centavos inteiros. 99.9 * 100 da 9989.999999999998: sem o round, o
// valor gravado fica um centavo abaixo do cobrado.
function centavosDeReais(valor) {
  const n = Number(valor);
  return Number.isFinite(n) ? Math.round(n * 100) : null;
}

function cicloNormalizado(valor) {
  const v = String(valor === null || valor === undefined ? '' : valor).toLowerCase();
  if (['mensal', 'monthly', 'month', 'months', 'mes'].indexOf(v) >= 0) return 'mensal';
  if (['anual', 'annual', 'yearly', 'year', 'ano'].indexOf(v) >= 0) return 'anual';
  return null;
}

let aprovado = false;
let motivo = null;
let pagador = { nome: null, email: null, telefone: null };
let plano = null;
let valor_centavos = null;
let assinatura_externa_id = null;
let ciclo = null;

// Cada ramo le o no da propria consulta pelo nome. Referenciar no que nao rodou nesta
// execucao levanta erro no n8n, e e por isso que a leitura fica dentro do if do gateway em
// vez de usar $input, que mudaria de forma conforme o ramo.
if (gateway === 'mercadopago') {
  const p = $('Consulta Mercado Pago').first().json;
  const quem = p.payer || {};
  const fone = quem.phone || {};
  const meta = p.metadata || {};
  aprovado = p.status === 'approved';
  motivo = aprovado ? null : String(p.status_detail || p.status || 'sem status');
  pagador = {
    nome: [quem.first_name, quem.last_name].filter(Boolean).join(' ').trim() || null,
    email: quem.email || null,
    telefone: telefoneE164(String(fone.area_code || '') + String(fone.number || ''))
  };
  plano = meta.plano || meta.plan || null;
  valor_centavos = centavosDeReais(p.transaction_amount);
  assinatura_externa_id = String(meta.assinatura_externa_id || meta.preapproval_id || p.id || '');
  ciclo = cicloNormalizado(meta.ciclo || meta.frequency_type);
} else if (gateway === 'asaas') {
  const p = $('Consulta Asaas').first().json;
  // O payment do Asaas traz so o id do cliente; nome, e-mail e celular do dono vem do
  // /customers, e sem e-mail nao ha como criar a conta no Auth.
  const c = $('Consulta cliente Asaas').first().json;
  aprovado = ['CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH'].indexOf(String(p.status || '')) >= 0;
  motivo = aprovado ? null : String(p.status || 'sem status');
  pagador = {
    nome: c.name || null,
    email: c.email || null,
    telefone: telefoneE164(c.mobilePhone || c.phone)
  };
  plano = p.externalReference || p.description || null;
  valor_centavos = centavosDeReais(p.value);
  assinatura_externa_id = String(p.subscription || p.id || '');
  ciclo = cicloNormalizado(p.cycle);
} else if (gateway === 'stripe') {
  const ev = $('Consulta Stripe').first().json;
  const obj = (ev.data || {}).object || {};
  const quem = obj.customer_details || {};
  const meta = obj.metadata || {};
  aprovado = ['checkout.session.completed', 'invoice.paid', 'invoice.payment_succeeded'].indexOf(String(ev.type)) >= 0
    && String(obj.payment_status || 'paid') !== 'unpaid';
  motivo = aprovado ? null : String(ev.type || 'evento nao aprovado');
  pagador = {
    nome: quem.name || obj.customer_name || null,
    email: quem.email || obj.customer_email || null,
    telefone: telefoneE164(quem.phone)
  };
  plano = meta.plano || null;
  // A Stripe ja manda inteiro na MENOR unidade da moeda. Multiplicar por 100 aqui, como se
  // faz com Mercado Pago e Asaas, gravaria cem vezes o valor cobrado — e o erro passa por
  // qualquer validacao de tipo, porque continua sendo inteiro.
  if (typeof obj.amount_total === 'number') valor_centavos = obj.amount_total;
  else if (typeof obj.amount_paid === 'number') valor_centavos = obj.amount_paid;
  else if (typeof obj.amount === 'number') valor_centavos = obj.amount;
  assinatura_externa_id = String(obj.subscription || obj.id || '');
  ciclo = cicloNormalizado(meta.ciclo);
} else {
  throw new Error('gateway nao suportado: ' + gateway);
}

const evento = aprovado ? 'pagamento.confirmado' : 'pagamento.falhou';

// plano nulo NAO vira default: inventar plano e cobrar um valor e entregar outro. Quem
// recusa e a Edge Function, que conhece o catalogo de precos; a recusa vai para a
// fila_morta e um humano resolve.
const envelope = {
  evento: evento,
  versao: 1,
  id: uuidDeterministico(gateway + ':' + borda.evento_externo_id + ':' + evento),
  ocorrido_em: new Date().toISOString(),
  // tenant_id nulo de proposito: no pagamento.confirmado a barbearia ainda nao existe —
  // cria-la e justamente o trabalho de provisionar-tenant, que devolve o id.
  tenant_id: null,
  origem: 'gateway:' + gateway,
  dados: aprovado
    ? {
        gateway: gateway,
        evento_externo_id: borda.evento_externo_id,
        pagador: pagador,
        plano: plano,
        valor_centavos: valor_centavos,
        assinatura_externa_id: assinatura_externa_id || null,
        ciclo: ciclo
      }
    : {
        gateway: gateway,
        evento_externo_id: borda.evento_externo_id,
        assinatura_externa_id: assinatura_externa_id || null,
        motivo: motivo || 'nao aprovado'
      }
};

return [{ json: {
  evento: evento,
  aprovado: aprovado,
  assinatura_externa_id: assinatura_externa_id || null,
  motivo: motivo,
  envelope: envelope
} }];

const crypto = require('crypto');

const item = $input.first().json;

// Uma serializacao so, e e ela que vai no corpo da requisicao (contentType raw no no
// seguinte). Se o no de HTTP reserializasse o objeto, o HMAC seria sobre bytes diferentes
// dos enviados e o backend recusaria toda chamada.
const corpo_bruto = JSON.stringify(item.envelope);

const segredo = $env.SEGREDO_PONTE;
if (!segredo) throw new Error('variavel de ambiente ausente: SEGREDO_PONTE');

// ts dentro do texto assinado: sem ele a assinatura vale para sempre e a requisicao
// capturada pode ser reenviada. Quem confere a janela e a Edge Function.
const ts = String(Math.floor(Date.now() / 1000));
const assinatura = crypto.createHmac('sha256', segredo).update(ts + '.' + corpo_bruto, 'utf8').digest('hex');

return [{ json: { evento: item.evento, corpo_bruto: corpo_bruto, ts: ts, assinatura: assinatura } }];
